// A field ramp of `ftle` (colour_composition §1.2; render::colour::field_ramp): the `lin` compaction, polarity high,
// then `lut(grey)`, with the invalid lane, #141418 unless INVALID_OVERRIDE is 1, and the canvas background
// for a pixel that is not a system (REQ-COL-001, REQ-COL-108; R-467, R-511).
// @name ftle ramp
// @group Field ramp
// @about ftle on the lut(grey) ramp.
// @maps ftle [lin, polarity high]
// @glyph name
// @uniform INVALID_OVERRIDE: u32 = 0 [0, 1]
// @uniform INVALID_COLOUR: vec3<f32> = (1.0, 0.0, 1.0)
// @control INVALID_OVERRIDE toggle "Override the invalid colour" in "Invalid"
// @control INVALID_COLOUR colour "Invalid colour" in "Invalid"
// @uniform u_range: vec2<f32> = (0.0, 1.0)
// @control u_range hidden "Measured range"
fn colour(ctx: Ctx) -> vec3<f32> {
    handles_validity();
    let v = ctx.sample.ftle;
    if (ctx.validity.forbidden || ctx.sample.state == STATE_DECODE_FAILED) { return canvas_background(); }
    if (ctx.sample.state == STATE_SIM_FAILED || ctx.sample.state > STATE_DECODE_FAILED) { return select(PRESENT_INVALID, uniforms.INVALID_COLOUR, uniforms.INVALID_OVERRIDE != 0u); }
    if (!(has_ftle && ctx.sample.ftle_valid && (bitcast<u32>(v) & 0x7f800000u) != 0x7f800000u)) {
        if ((has_ftle && ctx.sample.ftle_valid) && (bitcast<u32>(v) & 0x7f800000u) == 0x7f800000u) { note_non_finite(); }
        return select(PRESENT_INVALID, uniforms.INVALID_COLOUR, uniforms.INVALID_OVERRIDE != 0u);
    }
    return ramp_grey(range_norm(v, uniforms.u_range.x, uniforms.u_range.y, false, vec2<f32>(0.0, 0.0)));
}

// A field ramp of `d_min` as a lightness (colour_composition §1.2, §4.1; render::colour::field_ramp): the `log`
// compaction, polarity high. A blank, unset or invalid sample returns 0: its style is drawn by the ramp's post.
// @name d_min lightness
// @group Brightness
// @about d_min as a lightness; its post draws its styles.
// @maps d_min [log, polarity high]
// @glyph ramp
fn brightness(ctx: Ctx) -> f32 {
    handles_validity();
    let v = ctx.sample.d_min;
    if (ctx.validity.forbidden || ctx.sample.state == STATE_DECODE_FAILED) { return 0.0; }
    if (ctx.sample.state == STATE_SIM_FAILED || ctx.sample.state > STATE_DECODE_FAILED) { return 0.0; }
    if (bitcast<u32>(v) == 0x7f800000u) { return 0.0; }
    if (!(bitcast<u32>(ctx.sample.d_min) != 0x7f800000u && (bitcast<u32>(v) & 0x7f800000u) != 0x7f800000u) || v < 0.0) {
        if ((bitcast<u32>(ctx.sample.d_min) != 0x7f800000u) && (bitcast<u32>(v) & 0x7f800000u) == 0x7f800000u) { note_non_finite(); }
        return 0.0;
    }
    return compact_log(v, 6.1035156e-5);
}

// The styles of the field ramp of `d_min` (colour_composition §4.1; render::colour::field_ramp): the background, "not yet"
// and the invalid lane over the combiner's output, #141418 unless INVALID_OVERRIDE is 1; every other colour as it is.
// @name d_min styles
// @group Post
// @about The background, not-yet and invalid styles of the d_min lightness, over the combiner's colour.
// @maps d_min [log, polarity high]
// @glyph name
// @uniform INVALID_OVERRIDE: u32 = 0 [0, 1]
// @uniform INVALID_COLOUR: vec3<f32> = (1.0, 0.0, 1.0)
// @control INVALID_OVERRIDE toggle "Override the invalid colour" in "Invalid"
// @control INVALID_COLOUR colour "Invalid colour" in "Invalid"
fn post(ctx: Ctx, rgb: vec3<f32>) -> vec3<f32> {
    handles_validity();
    let v = ctx.sample.d_min;
    if (ctx.validity.forbidden || ctx.sample.state == STATE_DECODE_FAILED) { return canvas_background(); }
    if (ctx.sample.state == STATE_SIM_FAILED || ctx.sample.state > STATE_DECODE_FAILED) { return select(PRESENT_INVALID, uniforms.INVALID_COLOUR, uniforms.INVALID_OVERRIDE != 0u); }
    if (bitcast<u32>(v) == 0x7f800000u) { return debug_not_yet(ctx.frag_xy); }
    if (!(bitcast<u32>(ctx.sample.d_min) != 0x7f800000u && (bitcast<u32>(v) & 0x7f800000u) != 0x7f800000u) || v < 0.0) {
        if ((bitcast<u32>(ctx.sample.d_min) != 0x7f800000u) && (bitcast<u32>(v) & 0x7f800000u) == 0x7f800000u) { note_non_finite(); }
        return select(PRESENT_INVALID, uniforms.INVALID_COLOUR, uniforms.INVALID_OVERRIDE != 0u);
    }
    return rgb;
}
